3	import java.math.BigDecimal;
4	import org.springframework.stereotype.Service;
5	
6	@Service
7	public class ResumoCompraService {
8	
9	    public ResumoCompra calcular(Pedido pedido) {
10	        Carrinho carrinho = new Carrinho(pedido.itens());
11	        if (!carrinho.valido()) {
12	            throw new PedidoRecusadoException("PEDIDO_INVALIDO");
13	        }
14	
15	        NivelClube nivel = Codigos.buscar(NivelClube.class, pedido.nivelClube())
16	                .orElseThrow(() -> new PedidoRecusadoException("NIVEL_CLUBE_INVALIDO"));
17	        Regiao regiao = Codigos.buscar(Regiao.class, pedido.regiao())
18	                .orElseThrow(() -> new PedidoRecusadoException("REGIAO_INVALIDA"));
19	        ModalidadeEntrega entrega = Codigos.buscar(ModalidadeEntrega.class, pedido.modalidadeEntrega())
20	                .orElseThrow(() -> new PedidoRecusadoException("MODALIDADE_INVALIDA"));
21	        if (!entrega.atende(carrinho)) {
22	            throw new PedidoRecusadoException("MODALIDADE_INDISPONIVEL");
23	        }
24	
25	        Cupom cupom = null;
26	        if (pedido.cupom() != null) {
27	            cupom = Codigos.buscar(Cupom.class, pedido.cupom())
28	                    .orElseThrow(() -> new PedidoRecusadoException("CUPOM_INVALIDO"));
29	            if (!cupom.aplicavel(carrinho)) {
30	                throw new PedidoRecusadoException("CUPOM_NAO_APLICAVEL");
31	            }
32	        }
33	
34	        FormaPagamento forma = Codigos.buscar(FormaPagamento.class, pedido.formaPagamento())
35	                .orElseThrow(() -> new PedidoRecusadoException("FORMA_PAGAMENTO_INVALIDA"));
36	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
37	        if (!forma.parcelasValidas(parcelas)) {
38	            throw new PedidoRecusadoException("PARCELAMENTO_INVALIDO");
39	        }
40	
41	        BigDecimal subtotal = carrinho.subtotal();
42	        BigDecimal frete = nivel.freteCobrado(entrega.frete(carrinho));
43	        BigDecimal desconto = cupom == null ? Dinheiro.ZERO : cupom.desconto(carrinho, frete);
44	        BigDecimal seguro = regiao.seguro(subtotal);
45	        BigDecimal total = subtotal.subtract(desconto).add(frete).add(seguro);
46	
47	        if (!forma.atende(total)) {
48	            throw new PedidoRecusadoException("FORMA_PAGAMENTO_INDISPONIVEL");
49	        }
50	        Cobranca cobranca = forma.cobrar(total, parcelas);
51	
52	        return new ResumoCompra(
53	                subtotal,
54	                desconto,
55	                frete,
56	                entrega.prazoDias(),
57	                seguro,
58	                cobranca.totalFinal().subtract(total),
59	                cobranca.totalFinal(),
60	                parcelas,
61	                cobranca.valorParcela(),
62	                nivel.credito(subtotal),
63	                nivel.brinde(subtotal));
64	    }
65	}
