1	package com.loja.resumo.calculo;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	
6	public enum FormaPagamento {
7	
8	    PIX {
9	        @Override
10	        Cobranca cobrar(BigDecimal total, int parcelas) {
11	            return Cobranca.avista(total.subtract(Dinheiro.sobre(total, new BigDecimal("0.05"))));
12	        }
13	    },
14	    CARTAO {
15	        private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
16	        private static final int PARCELAS_SEM_JUROS = 3;
17	        private static final int PARCELAS_MAXIMAS = 12;
18	
19	        @Override
20	        boolean parcelasValidas(int parcelas) {
21	            return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
22	        }
23	
24	        @Override
25	        Cobranca cobrar(BigDecimal total, int parcelas) {
26	            if (parcelas <= PARCELAS_SEM_JUROS) {
27	                return new Cobranca(total, Dinheiro.centavos(total.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128)));
28	            }
29	            BigDecimal fator = BigDecimal.ONE.add(TAXA_JUROS).pow(parcelas, MathContext.DECIMAL128);
30	            BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
31	            BigDecimal parcela = Dinheiro.centavos(total.multiply(TAXA_JUROS).divide(denominador, MathContext.DECIMAL128));
32	            return new Cobranca(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
33	        }
34	    },
35	    BOLETO {
36	        private static final BigDecimal TARIFA = new BigDecimal("3.49");
37	        private static final BigDecimal TOTAL_MAXIMO = new BigDecimal("1000");
38	
39	        @Override
40	        boolean atende(BigDecimal total) {
41	            return total.compareTo(TOTAL_MAXIMO) <= 0;
42	        }
43	
44	        @Override
45	        Cobranca cobrar(BigDecimal total, int parcelas) {
46	            return Cobranca.avista(total.add(TARIFA));
47	        }
48	    };
49	
50	    boolean parcelasValidas(int parcelas) {
51	        return parcelas == 1;
52	    }
53	
54	    boolean atende(BigDecimal total) {
55	        return true;
56	    }
57	
58	    abstract Cobranca cobrar(BigDecimal total, int parcelas);
59	}
