3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	final class Dinheiro {
7	
8	    static final BigDecimal ZERO = new BigDecimal("0.00");
9	
10	    private Dinheiro() {
11	    }
12	
13	    static BigDecimal centavos(BigDecimal valor) {
14	        return valor.setScale(2, RoundingMode.HALF_EVEN);
15	    }
16	
17	    static BigDecimal sobre(BigDecimal base, BigDecimal taxa) {
18	        return centavos(base.multiply(taxa));
19	    }
20	}
