3	import java.util.Arrays;
4	import java.util.Optional;
5	
6	final class Codigos {
7	
8	    private Codigos() {
9	    }
10	
11	    static <E extends Enum<E>> Optional<E> buscar(Class<E> tipo, String codigo) {
12	        if (codigo == null) {
13	            return Optional.empty();
14	        }
15	        return Arrays.stream(tipo.getEnumConstants())
16	                .filter(constante -> constante.name().equals(codigo))
17	                .findFirst();
18	    }
19	}
