package com.loja.resumo.calculo;

import java.math.BigDecimal;

public record Item(String nome, BigDecimal precoUnitario, Integer quantidade, BigDecimal pesoKg) {

    boolean valido() {
        return precoUnitario != null && precoUnitario.signum() > 0
                && quantidade != null && quantidade > 0
                && pesoKg != null && pesoKg.signum() > 0;
    }

    BigDecimal subtotal() {
        return precoUnitario.multiply(BigDecimal.valueOf(quantidade));
    }

    BigDecimal peso() {
        return pesoKg.multiply(BigDecimal.valueOf(quantidade));
    }
}

package com.loja.resumo.calculo;

import java.math.BigDecimal;
import java.util.List;

record Carrinho(List<Item> itens) {

    boolean valido() {
        return itens != null && !itens.isEmpty()
                && itens.stream().allMatch(item -> item != null && item.valido());
    }

    BigDecimal subtotal() {
        return itens.stream().map(Item::subtotal).reduce(Dinheiro.ZERO, BigDecimal::add);
    }

    BigDecimal peso() {
        return itens.stream().map(Item::peso).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

package com.loja.resumo.calculo;

import java.math.BigDecimal;

public enum Cupom {

    BEMVINDO10 {
        @Override
        boolean aplicavel(Carrinho carrinho) {
            return true;
        }

        @Override
        BigDecimal desconto(Carrinho carrinho, BigDecimal frete) {
            return Dinheiro.sobre(carrinho.subtotal(), new BigDecimal("0.10"));
        }
    },
    MENOS50 {
        @Override
        boolean aplicavel(Carrinho carrinho) {
            return carrinho.subtotal().compareTo(new BigDecimal("300")) >= 0;
        }

        @Override
        BigDecimal desconto(Carrinho carrinho, BigDecimal frete) {
            return new BigDecimal("50.00");
        }
    },
    FRETEGRATIS {
        @Override
        boolean aplicavel(Carrinho carrinho) {
            return true;
        }

        @Override
        BigDecimal desconto(Carrinho carrinho, BigDecimal frete) {
            return frete;
        }
    },
    LEVE3PAGUE2 {
        @Override
        boolean aplicavel(Carrinho carrinho) {
            return carrinho.itens().stream().anyMatch(item -> item.quantidade() >= 3);
        }

        @Override
        BigDecimal desconto(Carrinho carrinho, BigDecimal frete) {
            return carrinho.itens().stream()
                    .map(item -> item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade() / 3)))
                    .reduce(Dinheiro.ZERO, BigDecimal::add);
        }
    };

    abstract boolean aplicavel(Carrinho carrinho);

    abstract BigDecimal desconto(Carrinho carrinho, BigDecimal frete);
}

